import{_ as a,c as s,o as i,a2 as o}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"Permisos de macOS","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/permissions.md","filePath":"es/guide/permissions.md","lastUpdated":1793163976000}'),r={name:"es/guide/permissions.md"};function n(t,e,c,d,l,p){return i(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="permisos-de-macos" tabindex="-1">Permisos de macOS <a class="header-anchor" href="#permisos-de-macos" aria-label="Permalink to &quot;Permisos de macOS&quot;">​</a></h1><p>NueZip puede solicitar algunos permisos de macOS para ofrecer la mejor experiencia. Esta página explica para qué sirve cada permiso y cómo gestionarlos.</p><h2 id="archivos-y-carpetas" tabindex="-1">Archivos y carpetas <a class="header-anchor" href="#archivos-y-carpetas" aria-label="Permalink to &quot;Archivos y carpetas&quot;">​</a></h2><p>Para acceder a archivos en cualquier parte de tu sistema, NueZip necesita permiso de acceso a archivos.</p><p><strong>Para qué se usa</strong>: Leer archivos comprimidos, extraer contenidos y crear nuevos archivos.</p><p><strong>Gestionar</strong>: Configuración del sistema → <strong>Privacidad y seguridad</strong> → <strong>Archivos y carpetas</strong></p><p>Concede acceso cuando se te solicite durante el primer inicio. Puedes gestionar o revocar el acceso en cualquier momento.</p><h2 id="extension-de-finder" tabindex="-1">Extensión de Finder <a class="header-anchor" href="#extension-de-finder" aria-label="Permalink to &quot;Extensión de Finder&quot;">​</a></h2><p>NueZip incluye una extensión de Finder que añade opciones de menú contextual con clic derecho.</p><p><strong>Para qué se usa</strong>: Haz clic derecho en archivos comprimidos para extraer, comprimir o abrir con NueZip directamente desde Finder.</p><p><strong>Habilitar</strong>: Configuración del sistema → <strong>Privacidad y seguridad</strong> → <strong>Extensiones</strong> → <strong>Extensiones de Finder</strong> → Habilita <strong>NueZip</strong></p><h2 id="notificaciones" tabindex="-1">Notificaciones <a class="header-anchor" href="#notificaciones" aria-label="Permalink to &quot;Notificaciones&quot;">​</a></h2><p>NueZip puede mostrar notificaciones para operaciones de larga duración (extracción por lotes, compresión de archivos grandes).</p><p><strong>Para qué se usa</strong>: Avisarte cuando se completa una operación en segundo plano.</p><p><strong>Gestionar</strong>: Configuración del sistema → <strong>Notificaciones</strong> → <strong>NueZip</strong></p><h2 id="acceso-total-al-disco-opcional" tabindex="-1">Acceso total al disco (opcional) <a class="header-anchor" href="#acceso-total-al-disco-opcional" aria-label="Permalink to &quot;Acceso total al disco (opcional)&quot;">​</a></h2><p>Para extraer archivos a ubicaciones protegidas del sistema, NueZip puede solicitar Acceso total al disco.</p><p><strong>Para qué se usa</strong>: Escribir archivos extraídos en ubicaciones fuera de tu carpeta de usuario.</p><p><strong>Gestionar</strong>: Configuración del sistema → <strong>Privacidad y seguridad</strong> → <strong>Acceso total al disco</strong></p><p>Este permiso es opcional y solo es necesario si trabajas con ubicaciones de todo el sistema.</p><h2 id="restablecer-un-permiso-con-terminal" tabindex="-1">Restablecer un permiso con Terminal <a class="header-anchor" href="#restablecer-un-permiso-con-terminal" aria-label="Permalink to &quot;Restablecer un permiso con Terminal&quot;">​</a></h2><p>Si se descartó un cuadro de diálogo de permiso o el estado es incoherente, puedes restablecer los avisos de permiso de macOS usando <code>tccutil</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Restablecer permisos para NueZip</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> All</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.w3cub.nuezip</span></span></code></pre></div><p>Tras ejecutar <code>tccutil</code>, reinicia la app y vuelve a activar la función para que se te solicite de nuevo.</p><h2 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to &quot;Solución de problemas&quot;">​</a></h2><ul><li>Si no aparecen las notificaciones, comprueba que el permiso de <strong>Notificaciones</strong> esté concedido.</li><li>Tras cambiar los permisos, cierra y vuelve a abrir NueZip siempre para que los cambios surtan efecto.</li></ul><p>Para obtener más ayuda, visita la <a href="./troubleshooting.html">guía de solución de problemas</a>.</p>`,27)])])}const h=a(r,[["render",n]]);export{m as __pageData,h as default};
